<script setup lang="ts">import{formatLinearGradient}from'@fex-design/core/gradient/gradient';import{gradientPickerTrackClassName}from'@fex-design/styles/color-picker';import{cn}from'@fex/utils';import{computed,useAttrs}from'vue';import{useGradientPicker}from'./context';defineOptions({inheritAttrs:false});const attrs=useAttrs(),picker=useGradientPicker(),background=computed(()=>formatLinearGradient(picker.snapshot.value.value));function down(event:PointerEvent){if(event.target!==event.currentTarget||picker.snapshot.value.disabled)return;const element=event.currentTarget as HTMLElement,rect=element.getBoundingClientRect();picker.controller.addStop((event.clientX-rect.left)/rect.width)}</script><template><div v-bind="attrs" :class="cn(gradientPickerTrackClassName,attrs.class as string|undefined)" :style="[{'--gradient-picker-background':background},attrs.style]" @pointerdown="down"><slot :stops="picker.snapshot.value.value.stops"/></div></template>
